import '../../data/repositories/quran_repository.dart'; import '../../data/repositories/hifz_repository.dart'; import '../../data/models/ayah.dart';
class HifzPlan {final List<Ayah> revision,newAyahs;const HifzPlan({required this.revision,required this.newAyahs});}
class HifzEngine {final QuranRepository quran;final HifzRepository hifz;HifzEngine(this.quran,this.hifz);
 Future<HifzPlan> today({int target=3}) async {final due=await hifz.dueIds(limit:20);final revision=<Ayah>[];for(final id in due){final a=await quran.ayah(id);if(a!=null)revision.add(a);}int? cursor;final d=await hifz.database.db;final p=await d.rawQuery("SELECT MAX(ayah_id) m FROM hifz_progress WHERE introduced_at IS NOT NULL");cursor=p.first['m'] as int?;final newA=await quran.nextAyahs(cursor,target);return HifzPlan(revision:revision,newAyahs:newA);} }
